import{_ as e,c as r,o as i,af as n}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"36、【明夷】 離下坤上","description":"溫公易說 - 36、【明夷】 離下坤上","frontmatter":{"title":"36、【明夷】 離下坤上","description":"溫公易說 - 36、【明夷】 離下坤上"},"headers":[],"relativePath":"classics/wengong/037.md","filePath":"classics/wengong/037.md"}'),l={name:"classics/wengong/037.md"};function t(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="_36、【明夷】-離下坤上" tabindex="-1">36、【明夷】 離下坤上 <a class="header-anchor" href="#_36、【明夷】-離下坤上" aria-label="Permalink to “36、【明夷】 離下坤上”">​</a></h1><h3 id="彖曰-明入地中-明夷。內文明而外柔順-以蒙大難。文王以之-利艱貞。晦其明也-內難而能正其志-箕子以之。" tabindex="-1">彖曰：明入地中，明夷。內文明而外柔順，以蒙大難。文王以之，利艱貞。晦其明也，內難而能正其志，箕子以之。 <a class="header-anchor" href="#彖曰-明入地中-明夷。內文明而外柔順-以蒙大難。文王以之-利艱貞。晦其明也-內難而能正其志-箕子以之。" aria-label="Permalink to “彖曰：明入地中，明夷。內文明而外柔順，以蒙大難。文王以之，利艱貞。晦其明也，內難而能正其志，箕子以之。”">​</a></h3><h3 id="象曰-明入地中-明夷。君子以蒞眾-用晦而明。" tabindex="-1">象曰：明入地中，明夷。君子以蒞眾，用晦而明。 <a class="header-anchor" href="#象曰-明入地中-明夷。君子以蒞眾-用晦而明。" aria-label="Permalink to “象曰：明入地中，明夷。君子以蒞眾，用晦而明。”">​</a></h3><h3 id="初九-明夷于飛-垂其翼。君子於行-三日不食-有攸往-主人有言-象曰-君子於義-不食也。" tabindex="-1">初九：明夷于飛，垂其翼。君子於行，三日不食，有攸往，主人有言 象曰：君子於義，不食也。 <a class="header-anchor" href="#初九-明夷于飛-垂其翼。君子於行-三日不食-有攸往-主人有言-象曰-君子於義-不食也。" aria-label="Permalink to “初九：明夷于飛，垂其翼。君子於行，三日不食，有攸往，主人有言 象曰：君子於義，不食也。”">​</a></h3><h3 id="六二-明夷夷於左股-用拯馬壯-吉-象曰-六二之吉-順以則也。" tabindex="-1">六二：明夷夷於左股，用拯馬壯，吉 象曰：六二之吉，順以則也。 <a class="header-anchor" href="#六二-明夷夷於左股-用拯馬壯-吉-象曰-六二之吉-順以則也。" aria-label="Permalink to “六二：明夷夷於左股，用拯馬壯，吉 象曰：六二之吉，順以則也。”">​</a></h3><h3 id="九三-明夷於南狩-得其大首-不可疾貞-象曰-南狩之志-乃大得也。" tabindex="-1">九三：明夷於南狩，得其大首，不可疾貞 象曰：南狩之志，乃大得也。 <a class="header-anchor" href="#九三-明夷於南狩-得其大首-不可疾貞-象曰-南狩之志-乃大得也。" aria-label="Permalink to “九三：明夷於南狩，得其大首，不可疾貞 象曰：南狩之志，乃大得也。”">​</a></h3><h3 id="六四-入於左腹-獲明夷之心-於出門庭-象曰-入於左腹-獲心意也。" tabindex="-1">六四：入於左腹，獲明夷之心，於出門庭 象曰：入於左腹，獲心意也。 <a class="header-anchor" href="#六四-入於左腹-獲明夷之心-於出門庭-象曰-入於左腹-獲心意也。" aria-label="Permalink to “六四：入於左腹，獲明夷之心，於出門庭 象曰：入於左腹，獲心意也。”">​</a></h3><h3 id="六五-箕子之明夷-利貞-象曰-箕子之貞-明不可息也。" tabindex="-1">六五：箕子之明夷，利貞 象曰：箕子之貞，明不可息也。 <a class="header-anchor" href="#六五-箕子之明夷-利貞-象曰-箕子之貞-明不可息也。" aria-label="Permalink to “六五：箕子之明夷，利貞 象曰：箕子之貞，明不可息也。”">​</a></h3><p>君子之晦，以避難也。內修明德，不可息也。為人臣者，有箕子之正，則可也。無箕子之正，茍生以忘其君者，罪莫大焉。故曰利貞。</p><h3 id="上六-不明晦-初登於天-後入於地-象曰-初登於天-照四國也。後入於地-失則也。" tabindex="-1">上六：不明晦，初登於天，後入於地 象曰：初登於天，照四國也。後入於地，失則也。 <a class="header-anchor" href="#上六-不明晦-初登於天-後入於地-象曰-初登於天-照四國也。後入於地-失則也。" aria-label="Permalink to “上六：不明晦，初登於天，後入於地 象曰：初登於天，照四國也。後入於地，失則也。”">​</a></h3><p>上六之象，其言失則。何國家之所以立者，法也。故為工者，規矩繩墨不可去也。為國者，禮樂法度不可失也。度差而機失，綱絕而網紊，紀散而亂。法壞則國家從之。嗚呼，為人君者，可不慎哉。魯有慶父之難，齊桓公使仲孫湫視之，曰：魯可取乎？對曰：不可，猶秉周禮。周禮所以本也。然則法之於國，豈不重哉。</p>',11)])])}const f=e(l,[["render",t]]);export{b as __pageData,f as default};
